STOP = {"tablets", "tablet", "capsules", "capsule", "injection", "syrup", "suspension", "oral", "ip", "i", "p", "usp", "bp",
        "mg", "mcg", "ml", "g", "iu", "w", "v", "for", "and", "with", "of", "the", "gastro", "resistant", "tab", "cap", "inj",
        "syp", "susp", "nfi", "vet"}
