    idx: dict[str, list[AlertEntry]] = {}
    for a in alerts:
        if a.batch_no and a.batch_no.strip().lower() not in ("not mentioned",):
            idx.setdefault(norm_batch(a.batch_no), []).append(a)
    return idx

