from pathlib import Path
import re
vals = {}
for line in Path(".env").read_text().splitlines():
    if "=" in line and not line.startswith("#"):
        k, v = line.split("=", 1)
        v = v.strip().strip('"').strip("'")
        if len(v) >= 8:
            vals[k.strip()] = v
proj = Path.home() / ".claude" / "projects" / "C--Users-IBN-Documents-Claude-NeatHack"
hits = {}
for f in proj.rglob("*"):
    if f.is_file() and f.suffix in (".jsonl", ".json", ".txt", ".md", ".log"):
        try:
            txt = f.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        for k, v in vals.items():
            if v in txt:
                hits.setdefault(k, []).append(f.name)
print("key names checked:", list(vals))
print("hits:", {k: v for k, v in hits.items()} or "none")
# generic secret shapes in transcripts (names only, counts)
pat = re.compile(r"(sk-[A-Za-z0-9_-]{16,}|Bearer [A-Za-z0-9._-]{20,}|nl_[A-Za-z0-9]{16,})")
n = 0
for f in proj.glob("*.jsonl"):
    n += len(pat.findall(f.read_text(encoding="utf-8", errors="ignore")))
print("generic secret-shaped strings in session transcripts:", n)
PYEOF

