// One continuous narration (a single ElevenLabs request, so the delivery stays consistent), with per-scene start times from the character alignment.
// MODEL / STABILITY / SIMILARITY / STYLE env choose the variant. DRY=1 writes silent audio with proportional timings (no API call).
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const OUT = process.env.CLIP_DIR, KEY_FILE = process.env.KEY_FILE, DRY = process.env.DRY === "1";
const VOICE = process.env.VOICE_ID || "c6SfcYrb2t09NHXiT80T";
const SITE = process.env.DEMO_URL || "https://disclosure-desk.ibnweb3lab.workers.dev/";
const MODEL = process.env.MODEL || "eleven_v4";
const settings = { stability: Number(process.env.STABILITY ?? 0.4), similarity_boost: Number(process.env.SIMILARITY ?? 0.75), style: Number(process.env.STYLE ?? 0.35), use_speaker_boost: process.env.BOOST === "1" };
fs.mkdirSync(OUT, { recursive: true });
const UA = { "user-agent": "Mozilla/5.0 Chrome/124" };

// facts spoken in the video come from the live site, so the voice says what the screen shows
const gs = await (await fetch(new URL("/api/gapstudy", SITE), { headers: UA })).json();
const closed = gs.baseline.closed.medianAbsGapBps.toFixed(1), open = gs.baseline.open.medianAbsGapBps.toFixed(1);
const dbg = await (await fetch(new URL("/api/debug/bitget?t=AAPL", SITE), { headers: UA })).json().catch(() => ({ ok: false }));
const feedUp = dbg.ok === true;

const SCENES = [
  { id: "hero", say: "Members of Congress have to report their stock trades, but only weeks after they've made them, and by then the stock may have already moved, so the real question is whether it's too late to follow." },
  { id: "labels", say: "Disclosure Desk answers that by giving every reported trade one plain label: still early, too late, or went the other way." },
  { id: "example", say: "Let's open a real trade, straight from the official filings, where the card shows how much the stock moved before the filing was public, and how much it has moved since," },
  { id: "source", say: "and every trade links back to the original filing, so you can check it yourself." },
  { id: "ask", say: "You can also ask a question in plain English, right from the home page," },
  { id: "answer", say: "and an AI model writes a short summary, while our code rejects any number that isn't in the data, and the list underneath is computed straight from the filings, not generated." },
  { id: "list", say: "Stocks that Bitget also lists as twenty-four seven tokens carry a Bitget tag," },
  feedUp
    ? { id: "bitget_up", say: "and when you open one, you'll see the live token price, plus a practice order that never sends anything real." }
    : { id: "bitget_down", say: "though today Bitget's price feed is down, so the desk shows no price rather than a stale one." },
  { id: "proof", say: "The Proof page is where we tested the popular idea of copying Congress, and it doesn't reliably work, which we say plainly." },
  { id: "gap", say: `While US stocks were closed, tokens traded about ${closed} basis points away from their stock, compared with just ${open} when markets were open,` },
  { id: "outage", say: "and since Bitget's feed went down on October third, we make no claim about weekend gaps, only honest numbers." },
  { id: "how", say: "In short, we read the filings, check what the stock did since, and add the twenty-four seven view," },
  { id: "close", say: "all with no login, as a research tool, and not financial advice." },
];

const GAP = " "; // scenes join mid-sentence so the delivery runs on without stopping
const full = SCENES.map((s) => s.say).join(GAP);
let at = 0;
for (const s of SCENES) { s.startIdx = at; s.endIdx = at + s.say.length - 1; at += s.say.length + GAP.length; }

const mp3 = path.join(OUT, "narration.mp3");
let starts, ends;
if (DRY) {
  const total = Math.max(60, full.length / 15);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "lavfi", "-i", "anullsrc=r=44100:cl=mono", "-t", String(total), "-q:a", "9", mp3]);
  const per = total / full.length;
  starts = (i) => i * per; ends = (i) => (i + 1) * per;
} else {
  const KEY = fs.readFileSync(KEY_FILE, "utf8").trim();
  const r = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${VOICE}/with-timestamps?output_format=mp3_44100_128`, {
    method: "POST", headers: { "xi-api-key": KEY, "content-type": "application/json" },
    body: JSON.stringify({ text: full, model_id: MODEL, voice_settings: settings }),
  });
  if (!r.ok) throw new Error(`text-to-speech failed (HTTP ${r.status}): ${(await r.text()).slice(0, 240)}`);
  const j = await r.json();
  fs.writeFileSync(mp3, Buffer.from(j.audio_base64, "base64"));
  const a = j.alignment;
  if (!a || a.characters.join("") !== full) throw new Error("alignment does not match the text; cannot place scenes");
  starts = (i) => a.character_start_times_seconds[i]; ends = (i) => a.character_end_times_seconds[i];
}
const total = Number(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", mp3]).toString().trim());
const out = SCENES.map((s) => ({ id: s.id, say: s.say, start: starts(s.startIdx), end: ends(s.endIdx) }));
fs.writeFileSync(path.join(OUT, "resolved.json"), JSON.stringify({ voice: VOICE, model: MODEL, settings, total, feedUp, scenes: out }, null, 1));
for (const s of out) console.log(`${s.id.padEnd(12)} ${s.start.toFixed(1).padStart(6)}s -> ${s.end.toFixed(1).padStart(6)}s`);
console.log(`narration ${total.toFixed(1)}s, ${full.length} characters, model ${MODEL}, feed ${feedUp ? "up" : "down"}`);

