1	// Records the demo to follow ONE continuous narration take: every action is scheduled against the narration clock. No captions; a visible cursor only.
2	import { chromium } from "playwright-core";
3	import fs from "node:fs";
4	import path from "node:path";
5	
6	const SITE = process.env.DEMO_URL || "https://disclosure-desk.ibnweb3lab.workers.dev/";
7	const CHROME = process.env.CHROME_PATH, OUT = process.env.OUT_DIR, RESOLVED = process.env.RESOLVED;
8	const W = 1280, H = 720;
9	fs.mkdirSync(OUT, { recursive: true });
10	const META = JSON.parse(fs.readFileSync(RESOLVED, "utf8"));
11	const S = Object.fromEntries(META.scenes.map((s) => [s.id, s]));
12	const QUESTION = "Which recent trades are already too late to follow?";
13	
14	// A real answer from the live site, fetched just before recording. The page receives it after a short pause, so the
15	// timing of the take does not depend on how busy the language model is that minute (the content is unchanged).
16	const realAnswer = await (await fetch(new globalThis.URL("/api/ask", SITE), { method: "POST", headers: { "content-type": "application/json", "user-agent": "Mozilla/5.0 Chrome/124" }, body: JSON.stringify({ q: QUESTION }) })).text();
17	const parsed = JSON.parse(realAnswer);
18	console.log("real answer fetched:", parsed.mode, parsed.ids?.length, "rows");
19	
20	// likewise the live token study: fetched once from the live site, served instantly so the Proof card is not blank on camera
21	const realGap = await (await fetch(new globalThis.URL("/api/gapstudy", SITE), { headers: { "user-agent": "Mozilla/5.0 Chrome/124" } })).text();
22	console.log("gap study fetched:", JSON.parse(realGap).baseline?.closed?.medianAbsGapBps?.toFixed(1), "bps closed");
23	
24	const browser = await chromium.launch({ executablePath: CHROME, headless: true, args: ["--hide-scrollbars", "--force-device-scale-factor=1"] });
25	const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, colorScheme: "light", locale: "en-US", recordVideo: { dir: OUT, size: { width: W, height: H } } });
26	const t0 = Date.now();
27	
28	await ctx.addInitScript(() => {
29	  const css = `
30	  #__cur{position:fixed;left:-50px;top:-50px;width:22px;height:22px;margin:-3px 0 0 -3px;border-radius:50%;background:#fff;border:2px solid #14131f;box-shadow:0 3px 10px rgba(0,0,0,.35);z-index:2147483647;pointer-events:none;transition:transform .12s}
31	  #__cur.down{transform:scale(.8)}
32	  .__rip{position:fixed;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;border:3px solid #67d6c8;z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
33	  @keyframes __rip{to{transform:scale(3.2);opacity:0}}`;
34	  const boot = () => {
35	    if (document.getElementById("__cur")) return;
36	    const st = document.createElement("style"); st.textContent = css; document.documentElement.appendChild(st);
37	    const cur = document.createElement("div"); cur.id = "__cur"; document.documentElement.appendChild(cur);
38	    addEventListener("mousemove", (e) => { cur.style.left = e.clientX + "px"; cur.style.top = e.clientY + "px"; }, true);
39	    addEventListener("mousedown", (e) => { cur.classList.add("down"); const r = document.createElement("div"); r.className = "__rip"; r.style.left = e.clientX + "px"; r.style.top = e.clientY + "px"; document.documentElement.appendChild(r); setTimeout(() => r.remove(), 700); }, true);
40	    addEventListener("mouseup", () => cur.classList.remove("down"), true);
41	  };
42	  if (document.readyState === "loading") addEventListener("DOMContentLoaded", boot); else boot();
43	});
44	
45	const page = await ctx.newPage();
46	const errors = [];
47	page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
48	page.on("pageerror", (e) => errors.push(String(e)));
49	await page.route("**/api/ask", async (route) => { await new Promise((r) => setTimeout(r, 700)); await route.fulfill({ status: 200, contentType: "application/json; charset=utf-8", body: realAnswer }); });
50	
51	await page.route("**/api/gapstudy", (route) => route.fulfill({ status: 200, contentType: "application/json; charset=utf-8", body: realGap }));
52	
53	const wait = (ms) => page.waitForTimeout(ms);
54	let audioT0 = 0;
55	const log = (s) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s | narration ${audioT0 ? ((Date.now() - audioT0) / 1000).toFixed(1) : "-"}s] ${s}`);
56	// wait until `off` seconds after scene `id` begins in the narration (negative = before); logs when the previous step ran over
57	async function at(id, off = 0, label = "") {
58	  const due = audioT0 + (S[id].start + off) * 1000, d = due - Date.now();
59	  if (d > 0) await wait(d); else if (d < -500) log(`LATE ${(-d / 1000).toFixed(1)}s before ${id}${off >= 0 ? "+" : ""}${off} ${label}`);
60	}
