// Records the demo to follow ONE continuous narration take: every action is scheduled against the narration clock. No captions; a visible cursor only.
import { chromium } from "playwright-core";
import fs from "node:fs";
import path from "node:path";

const SITE = process.env.DEMO_URL || "https://disclosure-desk.ibnweb3lab.workers.dev/";
const CHROME = process.env.CHROME_PATH, OUT = process.env.OUT_DIR, RESOLVED = process.env.RESOLVED;
const W = 1280, H = 720;
fs.mkdirSync(OUT, { recursive: true });
const META = JSON.parse(fs.readFileSync(RESOLVED, "utf8"));
const S = Object.fromEntries(META.scenes.map((s) => [s.id, s]));
const QUESTION = "Which recent trades are already too late to follow?";

// A real answer from the live site, fetched just before recording. The page receives it after a short pause, so the
// timing of the take does not depend on how busy the language model is that minute (the content is unchanged).
const realAnswer = await (await fetch(new globalThis.URL("/api/ask", SITE), { method: "POST", headers: { "content-type": "application/json", "user-agent": "Mozilla/5.0 Chrome/124" }, body: JSON.stringify({ q: QUESTION }) })).text();
const parsed = JSON.parse(realAnswer);
console.log("real answer fetched:", parsed.mode, parsed.ids?.length, "rows");

// likewise the live token study: fetched once from the live site, served instantly so the Proof card is not blank on camera
const realGap = await (await fetch(new globalThis.URL("/api/gapstudy", SITE), { headers: { "user-agent": "Mozilla/5.0 Chrome/124" } })).text();
console.log("gap study fetched:", JSON.parse(realGap).baseline?.closed?.medianAbsGapBps?.toFixed(1), "bps closed");

const browser = await chromium.launch({ executablePath: CHROME, headless: true, args: ["--hide-scrollbars", "--force-device-scale-factor=1"] });
const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, colorScheme: "light", locale: "en-US", recordVideo: { dir: OUT, size: { width: W, height: H } } });
const t0 = Date.now();

await ctx.addInitScript(() => {
  const css = `
  #__cur{position:fixed;left:-50px;top:-50px;width:22px;height:22px;margin:-3px 0 0 -3px;border-radius:50%;background:#fff;border:2px solid #14131f;box-shadow:0 3px 10px rgba(0,0,0,.35);z-index:2147483647;pointer-events:none;transition:transform .12s}
  #__cur.down{transform:scale(.8)}
  .__rip{position:fixed;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;border:3px solid #67d6c8;z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
  @keyframes __rip{to{transform:scale(3.2);opacity:0}}`;
  const boot = () => {
    if (document.getElementById("__cur")) return;
    const st = document.createElement("style"); st.textContent = css; document.documentElement.appendChild(st);
    const cur = document.createElement("div"); cur.id = "__cur"; document.documentElement.appendChild(cur);
    addEventListener("mousemove", (e) => { cur.style.left = e.clientX + "px"; cur.style.top = e.clientY + "px"; }, true);
    addEventListener("mousedown", (e) => { cur.classList.add("down"); const r = document.createElement("div"); r.className = "__rip"; r.style.left = e.clientX + "px"; r.style.top = e.clientY + "px"; document.documentElement.appendChild(r); setTimeout(() => r.remove(), 700); }, true);
    addEventListener("mouseup", () => cur.classList.remove("down"), true);
  };
  if (document.readyState === "loading") addEventListener("DOMContentLoaded", boot); else boot();
});

const page = await ctx.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));
await page.route("**/api/ask", async (route) => { await new Promise((r) => setTimeout(r, 700)); await route.fulfill({ status: 200, contentType: "application/json; charset=utf-8", body: realAnswer }); });

await page.route("**/api/gapstudy", (route) => route.fulfill({ status: 200, contentType: "application/json; charset=utf-8", body: realGap }));

const wait = (ms) => page.waitForTimeout(ms);
let audioT0 = 0;
const log = (s) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s | narration ${audioT0 ? ((Date.now() - audioT0) / 1000).toFixed(1) : "-"}s] ${s}`);
// wait until `off` seconds after scene `id` begins in the narration (negative = before); logs when the previous step ran over
async function at(id, off = 0, label = "") {
  const due = audioT0 + (S[id].start + off) * 1000, d = due - Date.now();
  if (d > 0) await wait(d); else if (d < -500) log(`LATE ${(-d / 1000).toFixed(1)}s before ${id}${off >= 0 ? "+" : ""}${off} ${label}`);
}
async function glide(x, y, steps = 28) { await page.mouse.move(x, y, { steps }); }
async function center(sel) { const loc = typeof sel === "string" ? page.locator(sel).first() : sel; const b = await loc.boundingBox(); if (!b) throw new Error("no box for " + sel); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; }
async function clickOn(sel, steps = 30) {
  const loc = typeof sel === "string" ? page.locator(sel).first() : sel;
  await loc.scrollIntoViewIfNeeded();
  const { x, y } = await center(loc);
  await glide(x, y, steps); await wait(200);
  await page.mouse.down(); await wait(80); await page.mouse.up(); await wait(100);
}
const scrollDrawer = (y) => page.evaluate((v) => document.querySelector("#detail").scrollTo({ top: v, behavior: "smooth" }), y);
const bitgetId = META.feedUp ? "bitget_up" : "bitget_down";

// ---------------------------------------------------------------- load
await page.goto(SITE, { waitUntil: "load" });
await page.waitForSelector("#example [data-open]", { timeout: 30000 });
await page.waitForSelector(".row", { timeout: 30000 });
await wait(1500);
const readyMs = Date.now() - t0;
await glide(900, 360, 5);
audioT0 = Date.now();                       // the narration starts here
log("narration starts");

await glide(700, 300, 40); await wait(1800); await glide(330, 400, 50);          // hero

await at("labels", 0.2);                                                         // the labels
for (const i of [1, 2, 3]) { const { x, y } = await center(page.locator(".sbox").nth(i)); await glide(x, y, 26); await wait(800); }

await at("example", 0.1);                                                        // one real trade
await clickOn("#example [data-open]");
await page.waitForSelector("#detail:not([hidden]) .verdict-card", { timeout: 15000 });
await at("example", 5.2); await scrollDrawer(330);

await at("source", 0.0);                                                         // the source filing
await scrollDrawer(0); await wait(700);
{ const { x, y } = await center("#detail a[href][target=_blank]"); await glide(x, y, 30); }
await at("source", (S.source.end - S.source.start) - 1.1);
await clickOn("#d-close");

await at("ask", -0.3);                                                           // ask a question
await clickOn("#ask-q", 24);
await page.keyboard.type(QUESTION, { delay: 36 });
await wait(250);
await page.keyboard.press("Enter");
log("asked");

await at("answer", 0.3, "answer visible");                                       // the answer
await page.waitForFunction(() => { const a = document.querySelector("#answer"); return a && !a.hidden && !a.innerText.includes("Reading the filings"); }, null, { timeout: 15000 });
await page.evaluate(() => document.querySelector("#answer").scrollIntoView({ behavior: "smooth", block: "center" }));

await at("list", 0.2);                                                           // into the list, a Bitget-tagged trade
if (await page.locator("#show-ids").count()) { await clickOn("#show-ids"); await wait(1000); }
const rtRow = page.locator(".row", { has: page.locator(".rt") }).first();
const haveRt = (await rtRow.count()) > 0;
if (haveRt) await page.evaluate(() => document.querySelector(".row .rt")?.closest(".row")?.scrollIntoView({ behavior: "smooth", block: "center" }));
await at(bitgetId, -1.6, "open the trade");
if (haveRt) await clickOn(rtRow); else await clickOn(".row");
await page.waitForSelector("#detail:not([hidden]) .verdict-card", { timeout: 15000 });

await at(bitgetId, 0.4);                                                         // the Bitget part
await scrollDrawer(520);
const hasPrice = (await page.locator("#detail .kv").count()) > 0;
if (hasPrice !== META.feedUp) log("WARNING: the feed state changed since the narration was written");

await at("proof", 0.0);                                                          // proof
await clickOn("#d-close"); await wait(300);
await page.evaluate(() => window.scrollTo({ top: 0, behavior: "smooth" })); await wait(400);
await clickOn('.tab[data-view="proof"]');
await page.waitForSelector(".finding", { timeout: 15000 });
await page.evaluate(() => window.scrollTo(0, 0));                                // the new view must start at its top
await at("proof", 3.6);
await page.evaluate(() => window.scrollTo({ top: 460, behavior: "smooth" }));    // show the findings while the thesis is spoken

await at("gap", 0.2);
await page.waitForSelector("#gap-study .stat .n", { timeout: 15000 }).catch(() => {});
await page.evaluate(() => document.querySelector("#gap-study")?.scrollIntoView({ behavior: "smooth", block: "start" }));

await at("how", 0.0);                                                            // how it works, close
await page.evaluate(() => window.scrollTo({ top: 0, behavior: "smooth" })); await wait(500);
await clickOn('.tab[data-view="method"]');
await page.waitForSelector(".points", { timeout: 15000 });

await at("close", 0.0);
await clickOn('.tab[data-view="desk"]');
await page.evaluate(() => { window.scrollTo({ top: 0 }); const q = document.querySelector("#ask-q"), a = document.querySelector("#answer"); if (q) q.value = ""; if (a) a.hidden = true; });  // clean end frame
await at("close", (S.close.end - S.close.start) + 1.2);
log("finished");

const vpath = await page.video().path();
await ctx.close();
await browser.close();
fs.renameSync(vpath, path.join(OUT, "raw.webm"));
fs.writeFileSync(path.join(OUT, "timeline.json"), JSON.stringify({ readyMs, audioT0: (audioT0 - t0) / 1000, hasPrice, errors }, null, 1));
console.log("done. readyMs", readyMs, "errors", errors.length, "hasPrice", hasPrice);

