// Mixes the single narration take at the right offset, levels it, and muxes it with the trimmed video.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
const OUT = process.env.OUT_DIR, CLIP_DIR = process.env.CLIP_DIR, FINAL = process.env.FINAL;
const { readyMs, audioT0 } = JSON.parse(fs.readFileSync(path.join(OUT, "timeline.json"), "utf8"));
const trim = Math.max(0, (readyMs - 300) / 1000);
const delay = Math.max(0, Math.round((audioT0 - trim) * 1000));
const graph = `[1:a]aformat=sample_rates=44100:channel_layouts=mono,adelay=${delay}:all=1,loudnorm=I=-16:TP=-1.5:LRA=11[aout]`;
execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-ss", String(trim), "-i", path.join(OUT, "raw.webm"), "-i", path.join(CLIP_DIR, "narration.mp3"),
  "-filter_complex", graph, "-map", "0:v", "-map", "[aout]", "-c:v", "libx264", "-crf", "21", "-preset", "medium", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k", "-shortest", "-movflags", "+faststart", FINAL], { stdio: "inherit" });
const dur = execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", FINAL]).toString().trim();
console.log(`wrote ${FINAL} (${(fs.statSync(FINAL).size / 1048576).toFixed(1)} MB, ${Number(dur).toFixed(1)}s; narration starts ${(delay / 1000).toFixed(1)}s in)`);

