// RecallOps India: ONE continuous narration (a single ElevenLabs request), per-scene times from the character alignment.
// Method and voice settings come from the user's demo-video-kit (Voice C: eleven_v4, stability 0.18, similarity 0.75, style 0.65, boost off).
// Numbers spoken are read from demo/site/data.json so the voice says what the screen shows. DRY=1 = silent audio, no API call.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const OUT = process.env.CLIP_DIR, KEY_FILE = process.env.KEY_FILE, DRY = process.env.DRY === "1";
const VOICE = process.env.VOICE_ID || "c6SfcYrb2t09NHXiT80T", MODEL = process.env.MODEL || "eleven_v4";
const settings = { stability: Number(process.env.STABILITY ?? 0.18), similarity_boost: Number(process.env.SIMILARITY ?? 0.75), style: Number(process.env.STYLE ?? 0.65), use_speaker_boost: process.env.BOOST === "1" };
fs.mkdirSync(OUT, { recursive: true });
const D = JSON.parse(fs.readFileSync(process.env.DATA || "demo/site/data.json", "utf8"));

const ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const words = (n) => (n < 20 ? ONES[n] : n < 100 ? TENS[Math.floor(n / 10)] + (n % 10 ? "-" + ONES[n % 10] : "") : ONES[Math.floor(n / 100)] + " hundred" + (n % 100 ? " " + words(n % 100) : ""));

const r1 = D.rounds["1"], r2 = D.rounds["2"], m = D.metrics, rec = D.recovery;
const SCENES = [
  { id: "hero", say: "When India's drug regulator publishes batches that failed quality tests, a distributor has to find exactly those batches in its stock, and the customers who received them, so this is RecallOps India, an agent working from the real July alert against synthetic stock," },
  { id: "holds", say: `and for ${words(r1.counts.hold)} stock rows it finds strong evidence and places a hold,` },
  { id: "why", say: "where every hold shows why, because the batch, the product and the manufacturer all agree," },
  { id: "review", say: `while ${words(r1.counts.review)} uncertain rows go to a person instead of being held or cleared,` },
  { id: "round2", say: `and when a second alert arrives, the real August one, ${words(r2.reopened.length)} earlier decisions are reopened, so the holds grow to ${words(r2.counts.hold)},` },
  { id: "customers", say: `then it traces ${words(r2.customers.length)} customers who received held batches,` },
  { id: "unresolved", say: `and lists ${words(r2.downstream.unresolved_invoice_lines)} invoice lines with no batch number as unknown, not clear,` },
  { id: "draft", say: "and drafts a notice for each customer, which it never sends." },
  { id: "recovery", say: `When ${words(rec.events.length)} holds time out after they were written, it reads each one back, finds it held, and does not repeat it, so there are no duplicate holds.` },
  { id: "neatlogs", say: `Under the hood, neatlogs traces the baseline and the agent as separate workflows, so we could compare them on the same data, where the name-only baseline wrongly held ${words(m.baseline["1"].wrong_hold)} rows in round one, against ${m.agent["1"].wrong_hold === 0 ? "none" : words(m.agent["1"].wrong_hold)} for the agent,` },
  { id: "entire", say: "Entire checkpoints each build step, and we scanned its transcripts for keys before going public," },
  { id: "cfoai", say: "and cfo.ai prices a run as a hypothesis, where human review is ninety-nine point eight percent of the cost, about four dollars forty a run, against under a cent for the model." },
  { id: "close", say: "All of it on synthetic stock and one test set, with no customer validation, and not listed never means safe." },
