  const total = Math.max(60, full.length / 15);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "lavfi", "-i", "anullsrc=r=44100:cl=mono", "-t", String(total), "-q:a", "9", mp3]);
