    body: JSON.stringify({ text: full, model_id: MODEL, voice_settings: settings }),
  });
  if (!r.ok) throw new Error(`text-to-speech failed (HTTP ${r.status}): ${(await r.text()).slice(0, 240)}`);
  const j = await r.json();
  fs.writeFileSync(mp3, Buffer.from(j.audio_base64, "base64"));
  const a = j.alignment;
  if (!a || a.characters.join("") !== full) throw new Error("alignment does not match the text; cannot place scenes");
  starts = (i) => a.character_start_times_seconds[i]; ends = (i) => a.character_end_times_seconds[i];
}
