fs.writeFileSync(path.join(OUT, "resolved.json"), JSON.stringify({ voice: VOICE, model: MODEL, settings, total, scenes: out }, null, 1));
fs.writeFileSync(path.join(OUT, "script.txt"), full + "\n");
for (const s of out) console.log(`${s.id.padEnd(12)} ${s.start.toFixed(1).padStart(6)}s -> ${s.end.toFixed(1).padStart(6)}s`);
console.log(`narration ${total.toFixed(1)}s, ${full.length} characters, model ${MODEL}${DRY ? " (DRY, silent)" : ""}`);

