// Records the RecallOps case console to follow ONE continuous narration take: every action is scheduled against the narration clock.
// No captions; a visible cursor and click ripple only. Adapted from the user's demo-video-kit.
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const require = createRequire(path.resolve(process.env.KIT_DIR) + "/");
const { chromium } = require("playwright-core");
const SITE = process.env.DEMO_URL || "http://127.0.0.1:4173/";
const CHROME = process.env.CHROME_PATH, OUT = process.env.OUT_DIR, RESOLVED = process.env.RESOLVED;
const W = 1280, H = 720;
fs.mkdirSync(OUT, { recursive: true });
const META = JSON.parse(fs.readFileSync(RESOLVED, "utf8"));
const S = Object.fromEntries(META.scenes.map((s) => [s.id, s]));
const SHOTS = process.env.SHOTS === "1"; // one frame per scene for a quick visual check

const browser = await chromium.launch({ executablePath: CHROME, headless: true, args: ["--hide-scrollbars", "--force-device-scale-factor=1"] });
const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, colorScheme: "light", locale: "en-US", recordVideo: { dir: OUT, size: { width: W, height: H } } });
const t0 = Date.now();

await ctx.addInitScript(() => {
  const css = `
  #__cur{position:fixed;left:-50px;top:-50px;width:22px;height:22px;margin:-3px 0 0 -3px;border-radius:50%;background:#fff;border:2px solid #14131f;box-shadow:0 3px 10px rgba(0,0,0,.35);z-index:2147483647;pointer-events:none;transition:transform .12s}
  #__cur.down{transform:scale(.8)}
  .__rip{position:fixed;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;border:3px solid #67d6c8;z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
  @keyframes __rip{to{transform:scale(3.2);opacity:0}}`;
  const boot = () => {
    if (document.getElementById("__cur")) return;
    const st = document.createElement("style"); st.textContent = css; document.documentElement.appendChild(st);
    const cur = document.createElement("div"); cur.id = "__cur"; document.documentElement.appendChild(cur);
    addEventListener("mousemove", (e) => { cur.style.left = e.clientX + "px"; cur.style.top = e.clientY + "px"; }, true);
    addEventListener("mousedown", (e) => { cur.classList.add("down"); const r = document.createElement("div"); r.className = "__rip"; r.style.left = e.clientX + "px"; r.style.top = e.clientY + "px"; document.documentElement.appendChild(r); setTimeout(() => r.remove(), 700); }, true);
    addEventListener("mouseup", () => cur.classList.remove("down"), true);
  };
  if (document.readyState === "loading") addEventListener("DOMContentLoaded", boot); else boot();
});

const page = await ctx.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

const wait = (ms) => page.waitForTimeout(ms);
let audioT0 = 0;
const log = (s) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s | narration ${audioT0 ? ((Date.now() - audioT0) / 1000).toFixed(1) : "-"}s] ${s}`);
async function at(id, off = 0, label = "") {
  const due = audioT0 + (S[id].start + off) * 1000, d = due - Date.now();
  if (d > 0) await wait(d); else if (d < -500) log(`LATE ${(-d / 1000).toFixed(1)}s before ${id}${off >= 0 ? "+" : ""}${off} ${label}`);
  if (SHOTS) await page.screenshot({ path: path.join(OUT, `shot_${id}.png`) });
}
async function glide(x, y, steps = 28) { await page.mouse.move(x, y, { steps }); }
async function center(sel) { const loc = typeof sel === "string" ? page.locator(sel).first() : sel; const b = await loc.boundingBox(); if (!b) throw new Error("no box for " + sel); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; }
async function clickOn(sel, steps = 30) {
  const loc = typeof sel === "string" ? page.locator(sel).first() : sel;
  await loc.scrollIntoViewIfNeeded();
  const { x, y } = await center(loc);
  await glide(x, y, steps); await wait(200);
  await page.mouse.down(); await wait(80); await page.mouse.up(); await wait(100);
}
const smooth = (sel, block = "start") => page.evaluate(([s, b]) => document.querySelector(s)?.scrollIntoView({ behavior: "smooth", block: b }), [sel, block]);

// ---------------------------------------------------------------- load
await page.goto(SITE, { waitUntil: "load" });
await page.waitForSelector("body[data-ready='1'] .row", { timeout: 30000 });
await wait(1200);
const readyMs = Date.now() - t0;
await glide(900, 360, 5);
audioT0 = Date.now();                                  // the narration starts here
log("narration starts");

await glide(640, 40, 40); await wait(900); await glide(300, 150, 40);              // hero: title, tag, the stat strip
await at("holds", 0.2);
{ const { x, y } = await center("#n-hold"); await glide(x, y, 30); }               // 61 holds
await at("why", 0.1);
await clickOn("#rows .row");                                                       // first held row
await at("why", 1.8); { const { x, y } = await center("#detail .ev"); await glide(x, y, 26); }   // the evidence chips
await at("review", 0.0);
await clickOn("#f-review");                                                        // filter to the review queue
await wait(500);
await clickOn("#rows .row");
await at("round2", 0.0);
await clickOn("#r2"); await wait(600);                                             // the second alert
{ const { x, y } = await center("#n-re"); await glide(x, y, 26); }
await at("round2", 3.0); await smooth("#reopened", "start");                       // the reopened list
await at("customers", 0.0);
await clickOn('.tab[data-view="customers"]'); await wait(300);
{ const { x, y } = await center("#c-n"); await glide(x, y, 26); }
await at("unresolved", 0.0);
{ const { x, y } = await center("#c-un"); await glide(x, y, 26); }
await at("draft", 0.0);
await clickOn("#custlist .cust");                                                  // open a draft notice
await at("recovery", 0.0);
await clickOn('.tab[data-view="recovery"]'); await wait(400);
{ const { x, y } = await center("#tl .ev3"); await glide(x, y, 30); }
await at("neatlogs", 0.0);
await clickOn('.tab[data-view="evidence"]'); await wait(400);
await at("neatlogs", 4.0); { const { x, y } = await center("#cmp"); await glide(x, y, 30); }
await at("entire", 0.0);
await clickOn('.sub[data-sub="entire"]');
await at("cfoai", 0.0);
await clickOn('.sub[data-sub="cfoai"]');
await at("close", 0.0);
await clickOn('.tab[data-view="case"]'); await wait(200);
await page.evaluate(() => window.scrollTo(0, 0));
await at("close", (S.close.end - S.close.start) + 1.2);
log("finished");

const vpath = await page.video().path();
await ctx.close();
await browser.close();
fs.renameSync(vpath, path.join(OUT, "raw.webm"));
fs.writeFileSync(path.join(OUT, "timeline.json"), JSON.stringify({ readyMs, audioT0: (audioT0 - t0) / 1000, errors }, null, 1));
console.log("done. readyMs", readyMs, "errors", errors.length);

