// RecallOps India: ONE continuous narration (a single ElevenLabs request), per-scene times from the character alignment.
// Method and voice settings come from the user's demo-video-kit (Voice C: eleven_v4, stability 0.18, similarity 0.75, style 0.65, boost off).
// Numbers spoken are read from demo/site/data.json so the voice says what the screen shows. DRY=1 = silent audio, no API call.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const OUT = process.env.CLIP_DIR, KEY_FILE = process.env.KEY_FILE, DRY = process.env.DRY === "1";
const VOICE = process.env.VOICE_ID || "c6SfcYrb2t09NHXiT80T", MODEL = process.env.MODEL || "eleven_v4";
const settings = { stability: Number(process.env.STABILITY ?? 0.18), similarity_boost: Number(process.env.SIMILARITY ?? 0.75), style: Number(process.env.STYLE ?? 0.65), use_speaker_boost: process.env.BOOST === "1" };
fs.mkdirSync(OUT, { recursive: true });
const D = JSON.parse(fs.readFileSync(process.env.DATA || "demo/site/data.json", "utf8"));

const ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const words = (n) => (n < 20 ? ONES[n] : n < 100 ? TENS[Math.floor(n / 10)] + (n % 10 ? "-" + ONES[n % 10] : "") : ONES[Math.floor(n / 100)] + " hundred" + (n % 100 ? " " + words(n % 100) : ""));

const r1 = D.rounds["1"], r2 = D.rounds["2"], m = D.metrics, rec = D.recovery;
const SCENES = [
  { id: "hero", say: "When India's drug regulator publishes batches that failed quality tests, a distributor has to find exactly those batches in its stock, and the customers who received them, so this is RecallOps India, an agent working from the real July alert against synthetic stock," },
  { id: "holds", say: `and for ${words(r1.counts.hold)} stock rows it finds strong evidence and places a hold,` },
  { id: "why", say: "where every hold shows why, because the batch, the product and the manufacturer all agree," },
  { id: "review", say: `while ${words(r1.counts.review)} uncertain rows go to a person instead of being held or cleared,` },
  { id: "round2", say: `and when a second alert arrives, the real August one, ${words(r2.reopened.length)} earlier decisions are reopened, so the holds grow to ${words(r2.counts.hold)},` },
  { id: "customers", say: `then it traces ${words(r2.customers.length)} customers who received held batches,` },
  { id: "unresolved", say: `and lists ${words(r2.downstream.unresolved_invoice_lines)} invoice lines with no batch number as unknown, not clear,` },
  { id: "draft", say: "and drafts a notice for each customer, which it never sends." },
  { id: "recovery", say: `When ${words(rec.events.length)} holds time out after they were written, it reads each one back, finds it held, and does not repeat it, so there are no duplicate holds.` },
  { id: "neatlogs", say: `Under the hood, neatlogs traces the baseline and the agent as separate workflows, so we could compare them on the same data, where the name-only baseline wrongly held ${words(m.baseline["1"].wrong_hold)} rows in round one, against ${m.agent["1"].wrong_hold === 0 ? "none" : words(m.agent["1"].wrong_hold)} for the agent,` },
  { id: "entire", say: "Entire checkpoints each build step, and we scanned its transcripts for keys before going public," },
  { id: "cfoai", say: "and cfo.ai prices a run as a hypothesis, where human review is ninety-nine point eight percent of the cost, about four dollars forty a run, against under a cent for the model." },
  { id: "close", say: "All of it on synthetic stock and one test set, with no customer validation, and not listed never means safe." },
];

const GAP = " "; // scenes join mid-sentence so the delivery runs on without stopping
const full = SCENES.map((s) => s.say).join(GAP);
let at = 0;
for (const s of SCENES) { s.startIdx = at; s.endIdx = at + s.say.length - 1; at += s.say.length + GAP.length; }

const mp3 = path.join(OUT, "narration.mp3");
let starts, ends;
if (DRY) {
  const total = Math.max(60, full.length / 15);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "lavfi", "-i", "anullsrc=r=44100:cl=mono", "-t", String(total), "-q:a", "9", mp3]);
  const per = total / full.length;
  starts = (i) => i * per; ends = (i) => (i + 1) * per;
} else {
  const KEY = fs.readFileSync(KEY_FILE, "utf8").trim();
  const r = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${VOICE}/with-timestamps?output_format=mp3_44100_128`, {
    method: "POST", headers: { "xi-api-key": KEY, "content-type": "application/json" },
    body: JSON.stringify({ text: full, model_id: MODEL, voice_settings: settings }),
  });
  if (!r.ok) throw new Error(`text-to-speech failed (HTTP ${r.status}): ${(await r.text()).slice(0, 240)}`);
  const j = await r.json();
  fs.writeFileSync(mp3, Buffer.from(j.audio_base64, "base64"));
  const a = j.alignment;
  if (!a || a.characters.join("") !== full) throw new Error("alignment does not match the text; cannot place scenes");
  starts = (i) => a.character_start_times_seconds[i]; ends = (i) => a.character_end_times_seconds[i];
}
const total = Number(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", mp3]).toString().trim());
const out = SCENES.map((s) => ({ id: s.id, say: s.say, start: starts(s.startIdx), end: ends(s.endIdx) }));
fs.writeFileSync(path.join(OUT, "resolved.json"), JSON.stringify({ voice: VOICE, model: MODEL, settings, total, scenes: out }, null, 1));
fs.writeFileSync(path.join(OUT, "script.txt"), full + "\n");
for (const s of out) console.log(`${s.id.padEnd(12)} ${s.start.toFixed(1).padStart(6)}s -> ${s.end.toFixed(1).padStart(6)}s`);
console.log(`narration ${total.toFixed(1)}s, ${full.length} characters, model ${MODEL}${DRY ? " (DRY, silent)" : ""}`);

// Records the RecallOps case console to follow ONE continuous narration take: every action is scheduled against the narration clock.
// No captions; a visible cursor and click ripple only. Adapted from the user's demo-video-kit.
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const require = createRequire(path.resolve(process.env.KIT_DIR) + "/");
const { chromium } = require("playwright-core");
const SITE = process.env.DEMO_URL || "http://127.0.0.1:4173/";
const CHROME = process.env.CHROME_PATH, OUT = process.env.OUT_DIR, RESOLVED = process.env.RESOLVED;
const W = 1280, H = 720;
fs.mkdirSync(OUT, { recursive: true });
const META = JSON.parse(fs.readFileSync(RESOLVED, "utf8"));
const S = Object.fromEntries(META.scenes.map((s) => [s.id, s]));
const SHOTS = process.env.SHOTS === "1"; // one frame per scene for a quick visual check

const browser = await chromium.launch({ executablePath: CHROME, headless: true, args: ["--hide-scrollbars", "--force-device-scale-factor=1"] });
const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, colorScheme: "light", locale: "en-US", recordVideo: { dir: OUT, size: { width: W, height: H } } });
const t0 = Date.now();

await ctx.addInitScript(() => {
  const css = `
  #__cur{position:fixed;left:-50px;top:-50px;width:22px;height:22px;margin:-3px 0 0 -3px;border-radius:50%;background:#fff;border:2px solid #14131f;box-shadow:0 3px 10px rgba(0,0,0,.35);z-index:2147483647;pointer-events:none;transition:transform .12s}
  #__cur.down{transform:scale(.8)}
  .__rip{position:fixed;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;border:3px solid #67d6c8;z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
  @keyframes __rip{to{transform:scale(3.2);opacity:0}}`;
  const boot = () => {
    if (document.getElementById("__cur")) return;
    const st = document.createElement("style"); st.textContent = css; document.documentElement.appendChild(st);
    const cur = document.createElement("div"); cur.id = "__cur"; document.documentElement.appendChild(cur);
    addEventListener("mousemove", (e) => { cur.style.left = e.clientX + "px"; cur.style.top = e.clientY + "px"; }, true);
    addEventListener("mousedown", (e) => { cur.classList.add("down"); const r = document.createElement("div"); r.className = "__rip"; r.style.left = e.clientX + "px"; r.style.top = e.clientY + "px"; document.documentElement.appendChild(r); setTimeout(() => r.remove(), 700); }, true);
    addEventListener("mouseup", () => cur.classList.remove("down"), true);
  };
  if (document.readyState === "loading") addEventListener("DOMContentLoaded", boot); else boot();
});

const page = await ctx.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

const wait = (ms) => page.waitForTimeout(ms);
let audioT0 = 0;
const log = (s) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s | narration ${audioT0 ? ((Date.now() - audioT0) / 1000).toFixed(1) : "-"}s] ${s}`);
async function at(id, off = 0, label = "") {
  const due = audioT0 + (S[id].start + off) * 1000, d = due - Date.now();
  if (d > 0) await wait(d); else if (d < -500) log(`LATE ${(-d / 1000).toFixed(1)}s before ${id}${off >= 0 ? "+" : ""}${off} ${label}`);
  if (SHOTS) await page.screenshot({ path: path.join(OUT, `shot_${id}.png`) });
}
async function glide(x, y, steps = 28) { await page.mouse.move(x, y, { steps }); }
async function center(sel) { const loc = typeof sel === "string" ? page.locator(sel).first() : sel; const b = await loc.boundingBox(); if (!b) throw new Error("no box for " + sel); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; }
async function clickOn(sel, steps = 30) {
  const loc = typeof sel === "string" ? page.locator(sel).first() : sel;
  await loc.scrollIntoViewIfNeeded();
  const { x, y } = await center(loc);
  await glide(x, y, steps); await wait(200);
  await page.mouse.down(); await wait(80); await page.mouse.up(); await wait(100);
}
const smooth = (sel, block = "start") => page.evaluate(([s, b]) => document.querySelector(s)?.scrollIntoView({ behavior: "smooth", block: b }), [sel, block]);

// ---------------------------------------------------------------- load
await page.goto(SITE, { waitUntil: "load" });
await page.waitForSelector("body[data-ready='1'] .row", { timeout: 30000 });
await wait(1200);
const readyMs = Date.now() - t0;
await glide(900, 360, 5);
audioT0 = Date.now();                                  // the narration starts here
log("narration starts");

await glide(640, 40, 40); await wait(900); await glide(300, 150, 40);              // hero: title, tag, the stat strip
await at("holds", 0.2);
{ const { x, y } = await center("#n-hold"); await glide(x, y, 30); }               // 61 holds
await at("why", 0.1);
await clickOn("#rows .row");                                                       // first held row
await at("why", 1.8); { const { x, y } = await center("#detail .ev"); await glide(x, y, 26); }   // the evidence chips
await at("review", 0.0);
await clickOn("#f-review");                                                        // filter to the review queue
await wait(500);
await clickOn("#rows .row");
await at("round2", 0.0);
await clickOn("#r2"); await wait(600);                                             // the second alert
{ const { x, y } = await center("#n-re"); await glide(x, y, 26); }
await at("round2", 3.0); await smooth("#reopened", "start");                       // the reopened list
await at("customers", 0.0);
await clickOn('.tab[data-view="customers"]'); await wait(300);
{ const { x, y } = await center("#c-n"); await glide(x, y, 26); }
await at("unresolved", 0.0);
{ const { x, y } = await center("#c-un"); await glide(x, y, 26); }
await at("draft", 0.0);
await clickOn("#custlist .cust");                                                  // open a draft notice
await at("recovery", 0.0);
await clickOn('.tab[data-view="recovery"]'); await wait(400);
{ const { x, y } = await center("#tl .ev3"); await glide(x, y, 30); }
await at("neatlogs", 0.0);
await clickOn('.tab[data-view="evidence"]'); await wait(400);
await at("neatlogs", 4.0); { const { x, y } = await center("#cmp"); await glide(x, y, 30); }
await at("entire", 0.0);
await clickOn('.sub[data-sub="entire"]');
await at("cfoai", 0.0);
await clickOn('.sub[data-sub="cfoai"]');
await at("close", 0.0);
await clickOn('.tab[data-view="case"]'); await wait(200);
await page.evaluate(() => window.scrollTo(0, 0));
await at("close", (S.close.end - S.close.start) + 1.2);
log("finished");

const vpath = await page.video().path();
await ctx.close();
await browser.close();
fs.renameSync(vpath, path.join(OUT, "raw.webm"));
fs.writeFileSync(path.join(OUT, "timeline.json"), JSON.stringify({ readyMs, audioT0: (audioT0 - t0) / 1000, errors }, null, 1));
console.log("done. readyMs", readyMs, "errors", errors.length);

