import subprocess
from pathlib import Path
vals = []
for line in Path(".env").read_text().splitlines():
    if "=" in line and not line.startswith("#"):
        v = line.split("=", 1)[1].strip().strip('"').strip("'")
        if len(v) >= 8:
            vals.append(v)
def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True, encoding="utf-8", errors="ignore").stdout
refs = git("for-each-ref", "--format=%(refname)").split()
revs = git("rev-list", "--all").split()
print("refs:", len(refs), "| commits:", len(revs), "| entire refs:", sum(1 for r in refs if "entire" in r))
hits = 0
for v in vals:
    for target in set(refs) | set(revs):
        out = subprocess.run(["git", "grep", "-I", "-l", "-F", "-e", v, target], capture_output=True, text=True, encoding="utf-8", errors="ignore").stdout
        if out.strip():
            hits += 1
            print("HIT in", target[:40], "(value not printed)")
# working tree incl. untracked but not ignored files
tracked = git("ls-files", "-co", "--exclude-standard").splitlines()
wt = 0
for f in tracked:
    try:
        t = Path(f).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        continue
    if any(v in t for v in vals):
        wt += 1; print("WORKTREE HIT", f)
print("history/ref hits:", hits, "| working-tree hits:", wt, "| key values checked:", len(vals))
PYEOF

